CREATE TABLE IF NOT EXISTS users (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, roll_no VARCHAR(50), phone VARCHAR(20), password_hash VARCHAR(255) NOT NULL, token VARCHAR(64) UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS items (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, type VARCHAR(10) NOT NULL, title VARCHAR(150) NOT NULL, description TEXT NOT NULL DEFAULT '', category VARCHAR(50) NOT NULL DEFAULT 'other', location VARCHAR(150) NOT NULL, event_time TIMESTAMP NOT NULL, image_path VARCHAR(255), image_url VARCHAR(1000), image_hash VARCHAR(64), color_sig VARCHAR(255), verification_question VARCHAR(255), status VARCHAR(20) NOT NULL DEFAULT 'open', reporter_id INTEGER NOT NULL REFERENCES users(id), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS claims (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, item_id INTEGER NOT NULL REFERENCES items(id) ON DELETE CASCADE, claimant_id INTEGER NOT NULL REFERENCES users(id), answer TEXT NOT NULL DEFAULT '', proof_details TEXT NOT NULL DEFAULT '', status VARCHAR(20) NOT NULL DEFAULT 'pending', handover_code VARCHAR(6), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, resolved_at TIMESTAMP);
